{#- ===== master list of olympiads: code, name, pill colour ===== -#}
{%- set EXAMS = [
    ("ISO",  "Science Olympiad",           "#e8467c"),
    ("IMO",  "Maths Olympiad",             "#f0872b"),
    ("EIO",  "English Olympiad",           "#f0872b"),
    ("GKIO", "General Knowledge Olympiad", "#f0872b"),
    ("ICO",  "Computer Olympiad",          "#3aa76d"),
    ("IDO",  "Drawing Olympiad",           "#3aa76d"),
    ("NSSO", "Social Studies Olympiad",    "#e8467c"),
    ("NESO", "Essay Olympiad",             "#e8467c"),
    ("ASO",  "Astronomy Space Olympiad",   "#d4384f"),
    ("NLRO", "Logical Reasoning Olympiad", "#6b4fa0"),
    ("NHO",  "Hindi Olympiad",             "#6b4fa0"),
    ("AO",   "Abacus Olympiad",            "#3aa76d"),
    ("CIO",  "Commerce Olympiad",          "#6b4fa0")
] -%}

{#- ===== school city & state from the Customer's address ===== -#}
{%- set addr = frappe.db.sql("""
        select addr.city, addr.state
        from `tabAddress` addr
        inner join `tabDynamic Link` dl on dl.parent = addr.name
        where dl.link_doctype = 'Customer' and dl.link_name = %s
        order by addr.is_primary_address desc, addr.modified desc limit 1
    """, doc.school, as_dict=True) if doc.school else [] -%}
{%- set city_state = ((addr[0].city or "") ~ ", " ~ (addr[0].state or ""))|upper if addr else "" -%}

{#- ===== selected olympiads grouped by slot ===== -#}
{%- set slots = {} -%}
{%- for code, ename, color in EXAMS -%}
    {%- for r in doc.subjects_registered -%}
        {%- set val = (r.get("subject") or r.get("subject_code") or r.get("olympiad") or "")|string|upper -%}
        {%- if code == val or code in val.replace("-", " ").split() or ename|upper in val -%}
            {%- set slot = (r.get("slot") or "A")|string|upper|replace("SLOT-", "") -%}
            {%- set _ = slots.setdefault(slot, []).append(code) -%}
        {%- endif -%}
    {%- endfor -%}
{%- endfor -%}

<style>
.ht { font-family: Arial, Helvetica, sans-serif; color: #2b2b2b; }
.ht-card { width: 100%; border-collapse: collapse; border: 1px solid #cfc6b0;
           table-layout: fixed; page-break-inside: avoid; background: #fff; }
.ht-card td { vertical-align: top; }
.ht-left, .ht-left2 { width: 150px; background-color: #fbf2c9; text-align: center;
                      border-right: 1px solid #e3d9b8; }
.ht-left  { padding: 8px 6px 4px; }
.ht-left2 { padding: 2px 6px 6px; background-color: #f8ecb2; }
.ht-logo { width: 118px; }
.ht-logo-text { font-size: 34px; font-weight: 700; letter-spacing: 2px; color: #4a3b1f; line-height: 1; }
.ht-logo-sub { font-size: 7.5px; letter-spacing: 1.2px; color: #4a3b1f;
               border-top: 1px solid #8a7a4f; border-bottom: 1px solid #8a7a4f; padding: 1px 0; }
.ht-tag { font-size: 8.5px; font-style: italic; color: #6b5a2a; margin-top: 2px; }
.ht-photo { border: 1px solid #d9cda0; background: #fffdf2; height: 82px; margin: 6px 10px 0;
            font-size: 7.5px; color: #a99a6c; line-height: 1.5; padding: 18px 6px 0; }
.ht-sign-lbl { font-size: 8px; color: #5d5233; text-align: left; padding-left: 4px; }
.ht-sign-img { height: 26px; }
.ht-sign-name { font-size: 10px; font-weight: 700; }
.ht-sign-role { font-size: 8.5px; }
.ht-title { background: #4c3a77; color: #fff; text-align: center; padding: 6px 4px 3px;
            font-size: 17px; font-weight: 700; }
.ht-round { background: #4c3a77; text-align: center; padding-bottom: 6px; }
.ht-round b { display: inline-block; background: #f5c518; color: #3d2f5f; font-size: 12px;
              padding: 2px 26px; }
.ht-chev { color: #f5c518; font-size: 11px; letter-spacing: -2px; padding: 0 6px; }
.ht-det { padding: 12px 10px 6px 18px; }
.ht-det table { border-collapse: collapse; width: 100%; }
.ht-det td { padding: 3px 0; font-size: 12px; }
.ht-lbl { width: 122px; font-weight: 700; }
.ht-col { width: 10px; }
.ht-in { font-weight: 700; padding-left: 18px; }
.ht-rule { border-top: 1.5px solid #2b2b2b; margin: 8px 0 6px; }
.ht-slot-h { font-weight: 700; font-size: 12px; margin-bottom: 4px; }
.ht-ecell { width: 262px; padding: 4px 6px 4px 0; }
.ht-exam { width: 100%; border-collapse: collapse; background: #fdeef3; font-size: 8.5px; }
.ht-exam th { background: #e8467c; color: #fff; font-size: 9.5px; padding: 4px 3px; text-align: center; }
.ht-exam th.d { background: #6b4fa0; }
.ht-exam td { padding: 2px 3px; border-bottom: 1px solid #f7dde6; }
.ht-exam td.c { width: 46px; text-align: center; }
.ht-exam td.d { width: 74px; text-align: center; }
.ht-pill { display: inline-block; min-width: 38px; padding: 1px 5px; border-radius: 9px;
           color: #fff; font-weight: 700; font-size: 9px; text-align: center; }
.ht-notes { border-top: 1px solid #cfc6b0; padding: 4px 8px 2px; }
.ht-notes table { width: 100%; border-collapse: collapse; }
.ht-notes td { font-size: 7.2px; line-height: 1.35; vertical-align: top; padding-right: 8px; }
.ht-page { text-align: right; font-size: 8px; font-weight: 700; padding-top: 4px; }
.ht-foot { background: #4c3a77; padding: 3px 10px; }
.ht-foot table { width: 100%; border-collapse: collapse; }
.ht-foot td { color: #fff; font-size: 8px; text-align: center; }
.ht-foot span { color: #f5c518; }
</style>

<div class="ht">
<table class="ht-card">
    <tr>
        <td class="ht-left">
            <div class="ht-logo-text">ITO</div>
            <div class="ht-logo-sub">INDIAN TALENT OLYMPIAD</div>
            <div class="ht-tag">Building Bright Futures</div>
            <div class="ht-photo">Only for Round-2,<br>Affix Student<br>Passport Size<br>Photo</div>
        </td>

        <td style="padding:0;">
            <table style="width:100%;border-collapse:collapse;table-layout:fixed;">
            <tr>
                <td style="padding:0;">
                    <div class="ht-title">STUDENT HALL TICKET - CUM - ADMIT CARD</div>
                    <div class="ht-round">
                        <span class="ht-chev">&#187;&#187;&#187;</span>
                        <b>Round-1 &amp; Round-2</b>
                        <span class="ht-chev">&#171;&#171;&#171;</span>
                    </div>

                    <div class="ht-det">
                        <table>
                            <tr>
                                <td class="ht-lbl">School Code</td><td class="ht-col">:</td>
                                <td>{{ doc.ito_school_code or "" }}
                                    <span class="ht-in">Class :</span> {{ doc.get("class") or "" }}
                                    <span class="ht-in">Roll No. :</span> {{ doc.roll_no or "" }}</td>
                            </tr>
                            <tr><td class="ht-lbl">Student Name</td><td class="ht-col">:</td>
                                <td>{{ (doc.student_name or "")|upper }}</td></tr>
                            <tr><td class="ht-lbl">School Name</td><td class="ht-col">:</td>
                                <td>{{ (doc.full_name or "")|upper }}</td></tr>
                            <tr><td class="ht-lbl">School City<br>&amp; State</td><td class="ht-col">:</td>
                                <td>{{ city_state }}</td></tr>
                        </table>

                        <div class="ht-rule"></div>
                        <div class="ht-slot-h">Exams &amp; Slot selected</div>
                        <table>
                            {% for slot, codes in slots.items()|sort %}
                            <tr><td class="ht-lbl">Slot-{{ slot }} :</td><td class="ht-col"></td>
                                <td>{{ codes|join(", ") }}</td></tr>
                            {% else %}
                            <tr><td class="ht-lbl">Slot-A :</td><td class="ht-col"></td><td>&mdash;</td></tr>
                            {% endfor %}
                        </table>
                    </div>
                </td>

                <td class="ht-ecell">
                    <table class="ht-exam">
                        <tr><th colspan="2">Exams</th><th class="d">Exam Dates</th></tr>
                        {% for code, ename, color in EXAMS %}
                            {% set ns = namespace(date="N.A.") %}
                            {% for r in doc.subjects_registered %}
                                {% set val = (r.get("subject") or r.get("subject_code") or r.get("olympiad") or "")|string|upper %}
                                {% if (code == val or code in val.replace("-", " ").split() or ename|upper in val) and r.get("exam_date") %}
                                    {% set ns.date = frappe.utils.formatdate(r.get("exam_date"), "d MMM, yyyy") %}
                                {% endif %}
                            {% endfor %}
                        <tr>
                            <td class="c"><span class="ht-pill" style="background:{{ color }};">{{ code }}</span></td>
                            <td>{{ ename }}</td>
                            <td class="d">{{ ns.date }}</td>
                        </tr>
                        {% endfor %}
                    </table>
                </td>
            </tr>
            </table>
        </td>
    </tr>

    <tr>
        <td class="ht-left2">
            <div class="ht-sign-lbl">Signature of the candidate</div>
            <div class="ht-sign-name" style="padding-top:18px;">Ms. MADHUMATHI M.</div>
            <div class="ht-sign-role">Director</div>
        </td>
        <td class="ht-notes">
            <table>
            <tr>
                <td style="width:19%;"><b>Round-1 Exam:</b>
                    <div>+ <b>Date:</b> Mentioned Above</div>
                    <div>+ <b>Venue:</b> Your School</div>
                    <div>+ <b>Time:</b> School Hours</div></td>
                <td style="width:29%;"><b>Round-2 Exam:</b>
                    <div>+ Venue/Date/Time will be sent to your school in the month of January.</div>
                    <div>+ Please keep a xerox copy of this Admit card.</div>
                    <div>+ This admit card can be used for Round-1 &amp; Round-2.</div></td>
                <td style="width:29%;">+ If you qualify for Round-2, please affix your passport size color
                    photo duly attested (Signed &amp; Stamped) by school principal &amp; take a photocopy
                    &amp; carry both copies of this admit card to the exam centre.</td>
                <td style="width:23%;">+ Please carry HB Pencil or Blue/Black Ball Point pen to the exam.
                    <div class="ht-page">{{ page_label or "" }}</div></td>
            </tr>
            </table>
        </td>
    </tr>

    <tr>
        <td colspan="2" class="ht-foot">
            <table><tr>
                <td>Please visit our website: <span>www.indiantalent.org</span></td>
                <td>write to us at <span>support@indiantalent.org</span></td>
                <td>or Call - <span>1800 266 9192</span> (Toll Free)</td>
            </tr></table>
        </td>
    </tr>
</table>
</div>
